class Solution {
    private int best = 0;

    public int diameterOfBinaryTree(TreeNode root) {
        walk(root);
        return best;
    }

    private void walk(TreeNode node) {
        if (node == null) return;
        int left = depth(node.left);
        int right = depth(node.right);
        best = Math.max(best, left + right);   // 边数：不加 1
        walk(node.left);
        walk(node.right);
    }

    private int depth(TreeNode node) {
        if (node == null) return 0;
        return Math.max(depth(node.left), depth(node.right)) + 1;
    }
}

class Solution {
    private int best = 0;

    public int diameterOfBinaryTree(TreeNode root) {
        depth(root);
        return best;
    }

    // 返回深度，同时把「以当前节点为最高点的路径」贡献给 best
    private int depth(TreeNode node) {
        if (node == null) return 0;

        int left = depth(node.left);
        int right = depth(node.right);

        best = Math.max(best, left + right);   // 必须用成员变量
        return Math.max(left, right) + 1;      // 向上返回深度
    }
}

class Solution {
    public int diameterOfBinaryTree(TreeNode root) {
        int[] res = new int[1];   // res[0] 当输出参数，避免成员变量
        depth(root, res);
        return res[0];
    }

    private int depth(TreeNode node, int[] res) {
        if (node == null) return 0;

        int left = depth(node.left, res);
        int right = depth(node.right, res);

        res[0] = Math.max(res[0], left + right);
        return Math.max(left, right) + 1;
    }
}
